  input [number_of_channels-1:0] datain,
  output [number_of_channels-1:0] dataout
);parameter enable_bus_hold = "FALSE";
parameter use_differential_mode = "FALSE";
parameter number_of_channels = 1;

reg [number_of_channels-1:0] buffer;

always @ (posedge datain or negedge datain) begin
  buffer <= datain;
end

assign dataout = buffer;

endmodule

module top_module(clk, ar, sr, q);input clk, ar; 
  output q; 
  output reg [7:0] sr; 
  wire polynomial; 
  assign polynomial = sr[7]^sr[5]^sr[4]^sr[3]; 
