module counter2bit_async (
    input clk,
    input rst,
    output [1:0] q
);

    reg [1:0] q_reg;

    always @(posedge clk or posedge rst) begin
        if (rst)
            q_reg <= 2'b00;
        else
            q_reg <= q_reg + 1;
    end

    assign q = q_reg;

endmodule

