module up_counter_tc(
    input clk,
    input rst_n,
    output reg [7:0] count,
    output reg tc
);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 8'b00000000;
            tc <= 1'b0;
        end else begin
            if (count == 8'b11111111) begin
                tc <= 1'b1;
            end else begin
                count <= count + 1;
                tc <= 1'b0;
            end
        end
    end

endmodule

