Implement the Verilog module based on the following description.
Build a 16-bit down counter with synchronous active low reset signal and an enable signal. When the enable signal is high, the counter decrements by 1.
// (1) reset_n: Resets the counter to 16'b1111111111111111 when low.
// (2) enable: Enables the counter decrement operation when high.
// (3) q: The value of the counter.

module top_module(
    input clk,
    input reset_n,
    input enable,
    output reg [15:0] q);

code:
module top_module(
    input clk,
    input reset_n,
    input enable,
    output reg [15:0] q
);

    always @(posedge clk) begin
        if (!reset_n) begin
            // Synchronous reset: Reset the counter to 16'b1111111111111111
            q <= 16'b1111111111111111;
        end else if (enable) begin
            // Counter decrement: Decrement by 1 when enabled
            q <= q - 1;
        end
    end

endmodule

