module simple_memory
    (
		input rst_n, 
		input clk, 
		input rw,
		input [7:0] addr,
		input [7:0] data_in,
		output reg [7:0] data_out
    );

	reg [7:0] mem [255:0];
	reg [7:0] data_out_reg;

	always @(posedge clk or negedge rst_n)
	begin
		if (!rst_n)
		begin
			integer i;
			for (i = 0; i < 256; i = i + 1)
				mem[i] <= 8'b0;
			data_out_reg <= 8'b0;
		end
		else if (rw)
			mem[addr] <= data_in;
		else
			data_out_reg <= mem[addr];
	end

	assign data_out = data_out_reg;

endmodule

