module pedestrian_light (
    input clk,
    input areset,
    input button,
    input timer,
    output reg [1:0] state);

    parameter DONT_WALK = 2'b00, WALK = 2'b01, FLASHING = 2'b10;
    reg [3:0] count;
    reg [1:0] next_state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= DONT_WALK;
            count <= 4'd0;
        end else begin
            state <= next_state;
        end
    end

    always @(state or button or timer) begin
        case (state)
            DONT_WALK: begin
                if (button) next_state = WALK;
                else next_state = DONT_WALK;
            end
            WALK: begin
                if (count < 4'd9) next_state = WALK;
                else next_state = FLASHING;
            end
            FLASHING: begin
                if (count < 4'd4) next_state = FLASHING;
                else next_state = DONT_WALK;
            end
        endcase
    end

    always @(posedge clk) begin
        if (state == WALK || state == FLASHING) count <= count + 4'd1;
        else count <= 4'd0;
    end
endmodule

