module clk_divider(
    input clk,
    input reset,
    output reg clk_out
);

    reg [1:0] count;

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
            clk_out <= 0;
        end else begin
            if (count == 1) begin
                clk_out <= ~clk_out;
                count <= 0;
            end else begin
                count <= count + 1;
            end
        end
    end

endmodule

