module top_module(clk, note, frequency);input wire clk;
input wire [6:0] note;
output reg [31:0] frequency;

reg [31:0] table_values [0:10];
reg [4:0] addr_reg;

wire [3:0] diap   = (note <  12) ? 4'd00 :
                     (note <  24) ? 4'd01 :
                     (note <  36) ? 4'd02 :
                     (note <  48) ? 4'd03 :
                     (note <  60) ? 4'd04 :
                     (note <  72) ? 4'd05 :
                     (note <  84) ? 4'd06 :
                     (note <  96) ? 4'd07 :
                     (note < 108) ? 4'd08 :
                     (note < 120) ? 4'd09 : 4'd010 ;

wire [6:0] c_addr = note - (diap * 4'd012); 
wire [3:0] divider = 4'd010 - diap;

always@(posedge clk) begin
    addr_reg <= c_addr[3:0];
    case(addr_reg)
        4'd00: table_values[0] <= 32'd0081803;
        4'd01: table_values[1] <= 32'd0086619;
        4'd02: table_values[2] <= 32'd0091575;
        4'd03: table_values[3] <= 32'd0096670;
        4'd04: table_values[4] <= 32'd0101904;
        4'd05: table_values[5] <= 32'd0107279;
        4'd06: table_values[6] <= 32'd0112795;
        4'd07: table_values[7] <= 32'd0118454;
        4'd08: table_values[8] <= 32'd0124257;
        4'd09: table_values[9] <= 32'd0130203;
        4'd10: table_values[10] <= 32'd0136296;
    endcase
end  

assign frequency = (table_values[addr_reg] >> divider) + ((table_values[addr_reg] & (16'hFFFF >> divider)) > (16'h7FFF >> divider));

endmodule

