module top_module(clk, button, delay, clean);input clk, button;
input [8:0] delay;
output reg clean;

reg [8:0] delay_count;
reg button_last;

always@(posedge clk) begin
    if (button == 1 && button_last == 0) begin
        delay_count <= 0;
    end else if (button == 1 && delay_count < delay) begin
        delay_count <= delay_count + 1;
    end else if (button == 1 && delay_count == delay) begin
        clean <= 1;
        delay_count <= delay_count + 1;
    end else if (button == 0) begin
        clean <= 0;
        delay_count <= 0;
    end
    button_last <= button;
end

endmodule

