module top_module(input clk, input d, output reg [2:0] q);reg [2:0] shift_reg;
  always @(posedge clk) begin
    shift_reg <= {shift_reg[1:0], d};
  end
  always @(*) begin
    case(shift_reg)
      3'b000: q = shift_reg[0];
      3'b001: q = {shift_reg[1], shift_reg[0]};
      3'b010: q = {shift_reg[2], shift_reg[1]};
      3'b011: q = {shift_reg[2], shift_reg[1], shift_reg[0]};
      3'b100: q = {shift_reg[2], 2'b00};
      3'b101: q = {shift_reg[2], shift_reg[0], 1'b0};
      3'b110: q = {shift_reg[2], shift_reg[1], shift_reg[0]};
      3'b111: q = shift_reg;
    endcase
  end
endmodule

