    reg [3:0] ram [0:3];
    always @ (din)
        case(din)
            4'b0000: ram[0] = 1'b0;
            4'b0001: ram[1] = 1'b0;
            4'b0010: ram[2] = 1'b0;
            4'b0100: ram[3] = 1'b0;
            4'b1111: begin
                        ram[0] = 1'b1;
                        ram[1] = 1'b1;
                        ram[2] = 1'b1;
                        ram[3] = 1'b1;
                    end
            default: begin
                        ram[0] = 1'b1;
                        ram[1] = 1'b0;
                        ram[2] = 1'b0;
                        ram[3] = 1'b0;
                    end
        endcase

    reg q;
    always @(posedge clk)
        q <= ram[din];

    assign dout = q;

endmodule

