module top_module(
  input clk,
  input reset,
  input [1:0] select,
  input [15:0] data_in,
  output [3:0] decoder_out,
  output reg [15:0] data_out
);// 2-to-4 decoder implemented using NAND gates
  wire nand1_out, nand2_out, nand3_out, nand4_out;
  assign nand1_out = ~(select[0] & select[1]);
  assign nand2_out = ~(select[0] & ~select[1]);
  assign nand3_out = ~(~select[0] & select[1]);
  assign nand4_out = ~(~select[0] & ~select[1]);
  assign decoder_out = {nand1_out, nand2_out, nand3_out, nand4_out};

  // 16-bit register with synchronous active-high reset
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      data_out <= 16'h0000;
    end else if (select == 2'b01) begin
      data_out <= data_in;
    end
  end

  // Control logic to select between decoder and register
  always @(*) begin
    if (select == 2'b00) begin
      data_out = {4'b0000, decoder_out};
    end
  end

endmodule

