module up_down_counter (
    input clk,
    input reset,
    input en,
    input dir,
    output reg [5:0] q);

always @(posedge clk) begin
    if (reset)
        q <= 6'b000000;
    else if (en) begin
        if (dir)
            q <= q + 1;
        else
            q <= q - 1;
    end
end

endmodule

