description:
Design a circuit that splits a 16-bit input into two 8-bit outputs. The module first shifts the input 8 bits to the right, effectively dividing the input into high and low segments. It then assigns the upper 8 bits of the shifted output to `out_hi` and the lower 8 bits to `out_lo`, facilitating the separation of the input data into two manageable parts for further processing. This design effectively functions as a pipeline splitter, enhancing data handling in subsequent stages of a digital system.
module top_module(
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);

code:
module top_module(
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);reg [15:0] stage1_out;
reg [7:0] stage2_out_hi;
reg [7:0] stage2_out_lo;

// Stage 1: Barrel shifter
always @(*) begin
    stage1_out = in >> 8;
end

// Stage 2: Multiplexer
always @(*) begin
    stage2_out_hi = stage1_out[15:8];
    stage2_out_lo = stage1_out[7:0];
end

// Output
assign out_hi = stage2_out_hi;
assign out_lo = stage2_out_lo;

endmodule

