module gray_counter_2(
   input                clk,
   input                rst_n,
   input                en,

   output reg [1:0]     Q
);
    reg [1:0] bin;
    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            bin <= 2'b00;
            Q <= 2'b00;
        end
        else if(en) begin
            bin <= bin + 1;
            Q <= {bin[1], bin[1] ^ bin[0]};
        end
    end
endmodule

