module top_module(
    input clk,
    input areset,
    input x,
    output z
);reg [31:0] status;
reg [31:0] next;

always@(posedge clk or posedge areset) begin
    if(areset) status=0;
	 else begin
	 case(status)
	 0:begin
	 if(x==0) status=0;
	 else status=1;
	 end
	 1:begin
	 status=1;
	 end
	 endcase
	 end
end
assign z=(status==0&&x==1)||(status==1&&x==0);
endmodule

