module top_module(
  input clk,
  input reset,
  input in1,
  input in2,
  output reg out,
  output reg [5:0] state
);// State encoding
  parameter A = 6'b000001;
  parameter B = 6'b000010;
  parameter C = 6'b000100;
  parameter D = 6'b001000;
  parameter E = 6'b010000;
  parameter F = 6'b100000;

  // State registers
  reg [5:0] present_state, next_state;

  // Output register
  reg out_reg;

  // State transition and output logic
  always @(posedge clk, negedge reset) begin
    if (reset == 1'b0) begin
      present_state <= A;
      out_reg <= 1'b0;
    end
    else begin
      present_state <= next_state;
      out_reg <= present_state == F ? 1'b1 : present_state == C || present_state == D ? 1'b0 : out_reg;
    end
    case(present_state)
      A: begin
        next_state = in1 == 1'b1 && in2 == 1'b1 ? E : in1 == 1'b1 ? D : in2 == 1'b1 ? C : B;
      end
      B: begin
        next_state = in1 == 1'b1 && in2 == 1'b1 ? C : in1 == 1'b1 ? E : in2 == 1'b1 ? F : A;
      end
      C: begin
        next_state = in1 == 1'b1 && in2 == 1'b1 ? F : in1 == 1'b1 ? A : in2 == 1'b1 ? B : D;
      end
      D: begin
        next_state = in1 == 1'b1 && in2 == 1'b1 ? B : in1 == 1'b1 ? C : in2 == 1'b1 ? E : F;
      end
      E: begin
        next_state = in1 == 1'b1 && in2 == 1'b1 ? A : in1 == 1'b1 ? F : in2 == 1'b1 ? D : C;
      end
      F: begin
        next_state = in1 == 1'b1 && in2 == 1'b1 ? D : in1 == 1'b1 ? B : in2 == 1'b1 ? A : E;
      end
    endcase
  end

  // Output assignments
  assign out = out_reg;
  assign state = present_state;

endmodule

