    reg VNB;

    // Outputs are wires
    reg Y; // Changed from wire to reg

    // Internal signals
    reg [4:0] state = 5'b00000;
    reg [4:0] count = 5'b00000;

    // Uncomment the next line if the module sky130_fd_sc_hdll__a222oi is defined
    // sky130_fd_sc_hdll__a222oi dut (.A1(A1), .A2(A2), .B1(B1), .B2(B2), .C1(C1), .C2(C2), .VPWR(VPWR), .VGND(VGND), .VPB(VPB), .VNB(VNB), .Y(Y));

