        if (count < 24) begin
            count <= count + 1;
        end else begin
            count <= 0;
            state <= 5'b00000;
        end
        if (count < 16) begin
            state <= {state[3:0], 1'b0};
        end else if (count < 24) begin
            state <= {state[3:0], 1'b1};
        end
    end

endmodule

